command:
cd /work/crate && cp src/function.rs /work/tmp/function.rs.original && cp tests/functions.rs /work/tmp/functions.rs.original && python3 - <<'PY'
from pathlib import Path
p = Path('tests/functions.rs')
s = p.read_text()
needle = '#[test]\nfn shell_error() {'
new = r'''#[test]
fn shell_dry_run_does_not_execute() {
  let output = Test::new()
    .arg("--dry-run")
    .justfile(
      "
        value := shell('echo assignment > executed')

        default parameter=(shell('echo parameter >> executed')):
          @echo {{value}} {{parameter}} {{shell('echo interpolation >> executed')}}
      ",
    )
    .stderr(
      "echo shell(\"echo assignment > executed\") shell(\"echo parameter >> executed\") shell(\"echo interpolation >> executed\")\n",
    )
    .success();

  assert!(!output.tempdir.path().join("executed").exists());
}

#[test]
fn shell_dry_run_error() {
  Test::new()
    .args(["--dry-run", "--evaluate", "value"])
    .justfile("value := shell('exit 1')")
    .stdout(r#"shell("exit 1")"#)
    .success();
}

#[test]
fn shell_dry_run_args() {
  Test::new()
    .arg("--dry-run")
    .justfile(
      r#"
        command := 'printf "%s\n" "$@"'
        text := 'hello'

        default:
          echo {{shell(command, '', text + ' world', '"quoted"', 'back\slash', "line\nbreak\ttab\rcarriage", '☃')}}
      "#,
    )
    .stderr(
      r#"
        echo shell("printf \"%s\\n\" \"$@\"", "", "hello world", "\"quoted\"", "back\\slash", "line\nbreak\ttab\rcarriage", "☃")
      "#,
    )
    .success();
}

#[test]
fn shell_dry_run_nested() {
  Test::new()
    .args(["--dry-run", "--evaluate", "value"])
    .justfile("value := shell(shell('exit 1'), shell('exit 2'), `exit 3`)")
    .stdout(r#"shell("shell(\"exit 1\")", "shell(\"exit 2\")", "`exit 3`")"#)
    .success();
}

'''
assert needle in s
p.write_text(s.replace(needle, new + needle))
PY
command -v cargo
RUSTUP_AUTO_INSTALL=0 cargo --version
cat tests/tempdir.rs
